{"command":"kubectl create cm -n default app-nginx --from-file=default.conf <<'EOF'
server {
  listen 80;
  location /app {
    return 200 'hello from the app';
  }
  location / {
    return 200 'app root works';
  }
}
EOF"}

{"command":"cat > /tmp/nginx.conf <<'EOF'
server { listen 80; location /app { return 200 'app-route by traefik works'; } location / { return 404 'root not handled'; } }
EOF
kubectl create cm -n default app-nginx --from-file=default.conf=/tmp/nginx.conf
sleep 3
kubectl get cm -n default app-nginx; echo; kubectl get pods -n default -o wide; kubectl get deploy app -n default"}

